from toollib import *
GUIDES=[
tool('clamav','A free virus scanner that checks files and folders for known malware.',
 ['ClamAV is an open-source virus scanner. It has no window: you run a scan from Terminal and read the list it prints.','It is a second opinion, not a replacement for the built-in protection (Microsoft Defender on Windows, XProtect on a Mac).'],
 ['A second scan when you suspect malware.','Checking a USB stick or a folder of downloads before opening it.','Linux computers, which have no built-in scanner.'],
 [S('Open Terminal (see "Opening Terminal and typing a command"). On Windows, open it as administrator.'),
  S('Update the virus definitions first. Type freshclam and press Enter.', see='"Downloading daily.cvd" and "database updated". It takes a minute or two.', tip='Linux: sudo freshclam. Windows: if freshclam says the config file is missing, run MendKit\'s malware scan recipe once; it sets ClamAV up.'),
  S('Scan your user folder. Windows: clamscan -r -i %USERPROFILE%   Mac and Linux: clamscan -r -i ~', see='Nothing for a while (it can take 30 minutes or more), then a SCAN SUMMARY.', tip='-r means look in every folder inside; -i means only list infected files.'),
  S('Read the summary at the end.')],
 results=['"Infected files: 0" means nothing known was found.','Each line ending FOUND names a file and the malware it matched, for example Downloads/setup.exe: Win.Trojan.Agent FOUND.','"Known viruses" is how many patterns it checked against.'],
 trouble=['"command not found": the install did not finish; reinstall from Tools.','A FOUND file you trust (for example a password tool or crack-detection test file) can be a false alarm. Search the name it matched.'],
 care=['ClamAV only reports. To remove a file it found, delete it yourself or quarantine it with Malwarebytes. Do not delete files in Windows or System folders.'],
 time='30 minutes to 2 hours', level='Takes care', ui='cli', related=['malwarebytes','adwcleaner','basics-terminal']),

tool('bleachbit','Clears caches, temporary files and browser junk to free space.',
 ['BleachBit deletes files that programs leave behind: caches, temporary files, logs, crash reports and browser history.','You choose what to clean from a list, and it shows what it would delete before deleting anything.'],
 ['The drive is nearly full.','A browser is slow or misbehaving and clearing its cache did not help.','Clearing private browsing traces before passing a computer on.'],
 [S('Close the browsers and other programs you want to clean.', tip='BleachBit cannot clean a program that is open.'),
  S('Open BleachBit.', see='The first time, a Preferences window. Close it. The main window has a list of programs on the left with tick boxes.'),
  S('Tick System, then Temporary files and Cache under it. Under each browser tick Cache. Leave Passwords, Form history and Cookies unticked unless the person wants to be signed out of everything.', warn='Items marked in red or with a warning (such as Free disk space, or Memory) are slow or risky. Leave them unticked.'),
  S('Click Preview.', see='The files that would be deleted and how much space would be freed. Nothing is deleted yet.'),
  S('If the list looks right, click Clean, then Delete to confirm.', see='"Disk space recovered" with the amount.')],
 results=['"Disk space recovered" is what was freed.','"Files deleted" counts the files removed. A few "permission denied" lines are normal for files in use.'],
 trouble=['Nothing freed: the programs were open, or there was little junk.','Signed out of websites: Cookies was ticked. Sign in again.'],
 care=['Do not tick "Free disk space" on an SSD; it is slow and wears the drive for no benefit.'],
 time='5 minutes', related=['windirstat','mac-tools']),

tool('bcu','Removes many programs at once and cleans up what their uninstallers leave behind.',
 ['Bulk Crap Uninstaller lists every installed program, including hidden ones and Store apps, and can remove several in one go, quietly.','After removing, it finds leftover folders and settings and offers to delete them too.'],
 ['Removing bundled junk from a new laptop.','Removing toolbars, "PC optimisers" and other unwanted programs after a malware clean-up.','A program will not uninstall the normal way.'],
 [S('Open Bulk Crap Uninstaller and click Yes when Windows asks.', see='The first time, a short setup wizard. Accept the defaults and click Next until it finishes.'),
  S('Wait while it lists the installed programs.', see='Every program with its publisher, size and install date. Some rows are coloured: green means it can be removed quietly, grey are system parts.'),
  S('Sort by Install date to find recent arrivals, or by Publisher to find unknown makers.', tip='Search unknown names on the web before removing them. Drivers (Intel, Realtek, NVIDIA, AMD) and Microsoft Visual C++ Redistributables are needed by other programs: leave them.'),
  S('Tick the programs to remove and click Uninstall (Uninstall quietly if offered).', see='A confirmation listing what will be removed. Click Continue.'),
  S('Wait for the uninstallers. Some may show their own window; follow it.'),
  S('When it offers to look for leftovers, click Yes.', see='A list of leftover folders and registry entries, each with a confidence level.'),
  S('Keep only items marked Very good or Good ticked and click Delete selected.', warn='Leave Questionable and Bad items unticked; they may belong to something else.')],
 results=['Programs that were removed disappear from the list.','A red result means an uninstaller failed; try Uninstall again or use Revo Uninstaller.'],
 care=['Make a restore point first (MendKit\'s repairs do this automatically) before removing many programs at once.'],
 time='10 to 30 minutes', level='Takes care', related=['revo','autoruns']),

tool('smartmontools','Reads a drive\'s own health records (SMART) and runs its built-in self-tests.',
 ['Every hard drive and SSD keeps a health record: errors, bad areas, hours used and wear. smartmontools reads it with the smartctl command.','MendKit\'s drive health checks use it on Mac and Linux.'],
 ['A computer is slow, freezes, or makes clicking noises.','Before trusting an old or second-hand drive with someone\'s files.','MendKit says a drive is not Healthy and you want the details.'],
 [S('Open Terminal as administrator (Windows), or a normal Terminal on a Mac or Linux.'),
  S('List the drives: smartctl --scan', see='Lines such as /dev/sda or /dev/nvme0 (Linux), /dev/disk0 (Mac), /dev/sda or /dev/nvme0 (Windows).'),
  S('Read the health of the first drive. Windows and Linux: sudo smartctl -a /dev/sda (leave out sudo on Windows). Mac: sudo smartctl -a disk0', see='Several screens of information. The key line is "SMART overall-health self-assessment test result: PASSED".'),
  S('Optional: start a short self-test: sudo smartctl -t short /dev/sda. Wait the minutes it says, then read the result: sudo smartctl -l selftest /dev/sda')],
 results=['PASSED does not guarantee a healthy drive; also read the numbers below.','Hard drives: Reallocated_Sector_Ct, Current_Pending_Sector or Offline_Uncorrectable above 0 mean the surface is failing. Back up now.','SSDs: "Percentage Used" near or over 100%, or "Available Spare" below the threshold, mean it is worn out. "Media and Data Integrity Errors" above 0 is a bad sign.','Power_On_Hours shows the drive\'s age in hours (8,760 is one year switched on).'],
 trouble=['"Unable to detect device type": add -d sat for a USB drive, for example smartctl -a -d sat /dev/sdb.','Many USB enclosures hide SMART data entirely. Connect the drive directly if you can.'],
 time='5 minutes', level='Takes care', ui='cli', related=['crystaldiskinfo','nvme-cli','basics-terminal']),

tool('crystaldiskinfo','Shows each drive\'s health as Good, Caution or Bad, with temperature and hours used.',
 ['CrystalDiskInfo reads each drive\'s health record (SMART) and sums it up with a coloured label. The easiest way to check a drive on Windows.'],
 ['First thing on any slow or crashing Windows computer.','Before cloning or reusing a drive.'],
 [S('Open CrystalDiskInfo and click Yes when Windows asks.', see='A large coloured box: Health Status (Good in blue, Caution in yellow, Bad in red), the temperature, and a table of attributes.'),
  S('If there is more than one drive, click each drive\'s button along the top (labelled with its temperature and letter).'),
  S('Read Health Status, Temperature, Power On Hours and, for SSDs, the percentage beside Good (life left).')],
 results=['Good: no problems recorded.','Caution: the drive has started to fail (often reallocated or pending sectors). Back up now and plan to replace it.','Bad: replace it. Copy files off immediately, most important first.','Temperature over 50 °C for a hard drive or 70 °C for an SSD means poor cooling.'],
 trouble=['A drive in a USB enclosure may not show. Try Function, Advanced Feature, USB/Memory Card in the menu.'],
 time='2 minutes', related=['smartmontools','crystaldiskmark','mk-old-drive']),

tool('windirstat','Shows what is using the space on a drive, as a colour map of every file.',
 ['WinDirStat scans a drive and shows folders largest first, plus a map where each rectangle is a file sized by how big it is.'],
 ['The drive is full and you do not know why.','Finding forgotten large files: old videos, game installers, backups.'],
 [S('Open WinDirStat.', see='A box asking which drives to scan.'),
  S('Choose the C: drive (or All Local Drives) and click OK.', see='Pac-Man icons while it scans, which can take a few minutes. Then a folder list at the top and the colour map below.'),
  S('Click the arrow beside the biggest folders in the list to open them, largest first.'),
  S('Click a large rectangle in the map to find which file it is.'),
  S('To delete something, right-click it and choose Delete (to Recycle Bin).', warn='Do not delete anything inside Windows, Program Files, ProgramData or AppData unless you know what it is. Uninstall programs the normal way instead.')],
 results=['Huge pagefile.sys and hiberfil.sys files belong to Windows and are normal.','A large folder under Users is personal files: ask before deleting.','Windows.old (after an upgrade) can be removed with Disk Cleanup, Clean up system files.'],
 time='5 to 15 minutes', related=['wiztree','treesize','bleachbit']),

tool('testdisk','Recovers lost partitions (TestDisk) and deleted files and photos (PhotoRec).',
 ['Two recovery programs in one package. TestDisk repairs a drive whose partitions went missing ("drive needs formatting", "RAW"). PhotoRec digs deleted photos, documents and videos out of a drive or memory card, ignoring the folder structure.','Both run in a text window you move around with the arrow keys and Enter.'],
 ['A memory card or USB stick says it needs formatting.','Photos were deleted or a card was formatted by mistake.','A drive shows as unallocated or RAW after a crash.'],
 [S('Stop using the drive or card with the lost files straight away.', warn='Every new file written to it can overwrite what you want back. Never recover files onto the same drive they came from.'),
  S('Plug in a second drive with plenty of free space for the recovered files.'),
  S('Open Terminal as administrator and type photorec (sudo photorec on Mac and Linux). On Windows you can also double-click photorec_win.exe in its folder.', see='A list of drives with their sizes.'),
  S('Use the arrow keys to choose the drive or card with the lost files, and press Enter.', tip='Pick by size: a 64 GB card shows as about 62 GB.'),
  S('Choose the partition (or "No partition" for the whole thing) and press Enter on Search.'),
  S('Choose the file system type: Other for Windows drives and memory cards, ext2/ext3 for Linux.'),
  S('Choose Whole to search everything (Free only searches unused space, faster).'),
  S('Move to the second drive\'s folder where the files should go and press C to choose it.', see='A counter of files found by type. It can take hours.'),
  S('When it finishes, open the destination folder.', see='Folders named recup_dir.1, recup_dir.2 and so on, full of files with numbered names.')],
 extra=[sec('Lost partition: TestDisk',[S('Type testdisk (sudo testdisk on Mac/Linux). Choose Create for a log, pick the drive, accept the detected partition type, then Analyse and Quick Search.'),S('If the lost partition is listed in green, press Enter, then choose Write and confirm with Y. Restart the computer.', warn='Writing changes the partition table. If unsure, copy the files out instead: highlight the partition and press P to list and copy them.')],'steps')],
 results=['PhotoRec loses original file names and folders. Sort the recovered files by type or date, and use a photo viewer to find the ones wanted.','Partly overwritten files may open damaged or not at all.'],
 trouble=['A drive that clicks, is not detected, or is extremely slow is physically failing: stop, and use ddrescue to copy it first, or send it to a data recovery lab.'],
 time='1 to 6 hours', level='Needs care', ui='cli', need=['A second drive with enough free space'], related=['recuva','ddrescue','mk-old-drive']),

tool('lhm','Shows live temperatures, fan speeds, voltages and loads for every part.',
 ['LibreHardwareMonitor reads the computer\'s sensors: processor and graphics temperatures, fan speeds, power and load. MendKit\'s stress test reads temperatures through it on Windows.'],
 ['A computer is hot, loud or shuts itself off.','During MendKit\'s processor stress test.'],
 [S('Open LibreHardwareMonitor and click Yes when Windows asks.', see='A tree: the motherboard, processor (CPU), memory, graphics (GPU) and drives, each with Temperatures, Fans, Load and more.'),
  S('Open the processor section. Look at Temperatures: Core Max or Package is the one that matters.', see='Three columns: Value (now), Min and Max since it opened.'),
  S('Leave it open while you run a stress test or the job that causes trouble, then read the Max column.')],
 results=['Processor at rest: 30 to 55 °C is normal. Under full load: up to about 90 °C is acceptable for most laptops; over 95 °C means it is throttling or overheating.','Fans at 0 RPM under load mean a stopped fan (some quiet fans stop when cool, which is fine).','Drive over 60 °C: poor airflow.'],
 trouble=['Few or no sensors: it was not run as administrator.'],
 care=['High temperatures are usually dust: clean the vents and fans. Old laptops may need new thermal paste.'],
 time='5 minutes', related=['hwinfo','occt','mk-hardware']),

tool('unigetui','Updates all the apps on a Windows computer from one window.',
 ['UniGetUI is a friendly window on top of winget and other Windows package managers. It shows which apps have updates and installs them together.'],
 ['Bringing every app up to date after a repair.','Finding and installing common free programs.'],
 [S('Open UniGetUI.', see='A list of sections on the left: Discover packages, Software updates, Installed packages.'),
  S('Click Software updates.', see='Each app with an update, its current version and the new one.'),
  S('Tick the apps to update (or all) and click Update selected packages.', see='Progress for each app. Some may show their own installer window.'),
  S('Restart the computer if asked.')],
 results=['Apps that updated leave the list. Failed ones show a red mark; click it for the reason.'],
 trouble=['An app that keeps failing: close the app first, or update it from its own Help menu.'],
 time='10 to 30 minutes', related=['mk-updates']),

tool('nmap','Lists the devices on a network and the services each one offers.',
 ['Nmap scans a network to find which devices are there (computers, printers, cameras, routers) and which "doors" (ports) each one has open.'],
 ['Finding a printer\'s or camera\'s address.','Checking what is on a home network, for example after a security scare.'],
 [S('Find the network\'s address range. In MendKit, the Network check shows this computer\'s address, for example 192.168.1.20. The range is then 192.168.1.0/24.'),
  S('Open Terminal and type: nmap -sn 192.168.1.0/24 (with your own range).', see='"Nmap scan report for ..." for each device that answered, with its address and often its maker.'),
  S('To see what one device offers: nmap 192.168.1.50', see='A list such as 80/tcp open http, 631/tcp open ipp (a printer), 22/tcp open ssh.')],
 results=['Port 80 or 443: a web page; type the address in a browser to reach its settings (printers and routers).','Port 3389 (Remote Desktop) or 5900 (VNC) open on a home computer: remote control is switched on. Check it was meant to be.'],
 care=['Only scan networks you own or have permission to scan. Scanning other people\'s networks can be illegal.'],
 time='5 minutes', level='Takes care', ui='cli', related=['angryip','basics-terminal']),

tool('7zip','Opens and makes zip, 7z, rar and other compressed files.',
 ['7-Zip opens almost any compressed file (zip, 7z, rar, tar, iso) and can make zip or 7z files, with a password if wanted.'],
 ['A download ends in .7z or .rar and Windows cannot open it.','Packing a folder into one file to email or copy.'],
 [S('Windows: right-click the compressed file, choose Show more options, then 7-Zip, then Extract to "folder name\\".', see='A new folder beside the file with its contents.'),
  S('To make one: right-click a file or folder, Show more options, 7-Zip, Add to "name.zip".'),
  S('On a Mac and Linux, 7-Zip is a Terminal command: 7zz x file.7z (Mac) or 7z x file.7z (Linux) extracts into the current folder.')],
 trouble=['"Wrong password" or "Data error": the file is incomplete or damaged. Download it again.'],
 care=['Compressed files from unknown senders can hide malware. Scan them first.'],
 time='2 minutes', ui=['win-gui','cli'], related=['clamav']),

tool('rustdesk','Free remote support: lets a technician see and control this computer with permission.',
 ['RustDesk shows a technician your screen over the internet. It only works while it is open, and only with the ID and one-time password you read out.'],
 ['Your own trusted technician asks you to open it.','Helping a family member from a distance.'],
 [S('Open RustDesk.', see='"Your Desktop" with an ID (a long number) and a one-time password.'),
  S('Read the ID and password to the technician you contacted.', warn='Never do this for someone who called or messaged you out of the blue, whatever company they say they are from.'),
  S('When they connect, a window asks to accept. Click Accept.', see='A bar showing the session is active.'),
  S('To end the session at any time, click Disconnect or close RustDesk.', tip='The password changes each time, so they cannot reconnect later without you.')],
 care=['On a Mac, RustDesk needs Screen Recording and Accessibility permission (System Settings, Privacy & Security) before the technician can see or control anything.'],
 time='2 minutes', related=['basics-safety','remote-audit']),

tool('ventoy','Makes one USB stick that can start many different ISO files: installers and rescue systems.',
 ['Ventoy prepares a USB stick once. After that you just copy ISO files onto it, and the stick offers a menu of them at startup. No re-writing the stick for each image.'],
 ['Building a technician USB with Windows installers, Memtest86+, Hiren\'s and Linux rescue systems on one stick.'],
 [S('Plug in the USB stick.', warn='Installing Ventoy erases everything on the stick.'),
  S('Open Ventoy2Disk (click Start and type Ventoy). Click Yes when Windows asks.', see='A window with Device (the stick), the Ventoy version in package and on the device, and Install and Update buttons.'),
  S('Check the Device box shows your USB stick: its size and name. Read it twice.', warn='If more than one drive is listed, the wrong choice erases that drive instead.'),
  S('Click Install, then Yes to both warnings.', see='"Congratulations! Ventoy has been successfully installed to the device." The stick now shows as a drive called Ventoy.'),
  S('Copy ISO files onto the Ventoy drive in File Explorer, like any other files. Folders are fine.'),
  S('Eject the stick. To use it, start the computer from it (see "Starting a computer from a USB stick") and pick an ISO from the menu.')],
 results=['To update Ventoy later, click Update instead of Install: files on the stick are kept.'],
 trouble=['Ventoy menu says the image is not supported, or it freezes: choose the ISO, then press Enter on "Boot in grub2 mode" or "WIMBOOT mode".','Secure Boot error: on first boot, choose Enroll key from disk, ENROLL_THIS_KEY_IN_MOKMANAGER.cer, Continue, Yes and Reboot.'],
 time='10 minutes', level='Takes care', need=['A USB stick of 32 GB or more'], related=['mk-iso','rufus','basics-boot']),
]
